ALTER TABLE "dms"."upload_session" ADD CONSTRAINT "session_observation_bounds" CHECK (("dms"."upload_session"."observed_size" IS NULL OR "dms"."upload_session"."observed_size" BETWEEN 0 AND 1125899906842624) AND ("dms"."upload_session"."observed_etag" IS NULL OR length("dms"."upload_session"."observed_etag") BETWEEN 1 AND 256) AND ("dms"."upload_session"."failure_code" IS NULL OR "dms"."upload_session"."failure_code" IN ('SIZE_MISMATCH','CONTENT_TYPE_MISMATCH','SECURITY_ASSESSMENT_FAILED')));